// Cache tags for catalog/CMS data. Admin mutations call updateTag() on these
// so changes appear on the live storefront immediately.
export const TAGS = {
  products: "products",
  product: (slug: string) => `product:${slug}`,
  categories: "categories",
  banners: "banners",
  gallery: "gallery",
  settings: "settings",
  reviews: (productId: string) => `reviews:${productId}`,
} as const;
